const q=s=>document.querySelector(s),original=q('#paragraph').textContent;const proposal="Prioritize a small onboarding experiment before committing next quarter’s roadmap. The sample suggests setup drop-off, but its cause and connection to retention are unproven. Test a shorter setup against the current flow, measure activation, and examine retention separately.";q('#proposed').textContent=proposal;function tab(which){for(const n of ['reason','clarity']){q('#'+n+'-tab').setAttribute('aria-selected',String(n===which));q('#'+n+'-panel').hidden=n!==which;}}q('#reason-tab').onclick=()=>tab('reason');q('#clarity-tab').onclick=()=>tab('clarity');for(const n of ['reason','clarity'])q('#'+n+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();let other=n==='reason'?'clarity':'reason';tab(other);q('#'+other+'-tab').focus();}};q('#respond').onclick=()=>{if(!q('#evidence').value.trim()){q('#response-status').textContent='Add an evidence note first. A question or an uncertainty counts.';q('#evidence').focus();return;}q('#attached-note').textContent=q('#evidence').value.trim();q('#accept').disabled=false;q('#response-status').textContent='Your note is attached to this review. Cause and retention impact remain unresolved; this demo does not assess your evidence.';tab('clarity');q('#clarity-tab').focus();};q('#accept').onclick=()=>{q('#paragraph').textContent=proposal;q('#edit-status').textContent='Edit approved. Observation, hypothesis, and test are now distinct. Missing evidence stays unresolved.';};q('#restore').onclick=()=>{q('#paragraph').textContent=original;q('#edit-status').textContent='Original kept. You own the final wording.';};let timer,step=0;const labels=['begin with the draft','challenge the causal links','add the author’s evidence','approve a testable revision'];function show(i){document.querySelectorAll('.flow-step').forEach((e,n)=>e.classList.toggle('active',n===i));q('#flow-status').textContent='Step '+(i+1)+' of 4: '+labels[i]+'.';}q('#play').onclick=()=>{clearInterval(timer);step=0;show(step);if(matchMedia('(prefers-reduced-motion: reduce)').matches){document.querySelectorAll('.flow-step').forEach(e=>e.classList.add('active'));q('#flow-status').textContent='All four steps shown. Motion is reduced.';return;}timer=setInterval(()=>{step++;show(step);if(step===3)clearInterval(timer);},1500);};